<?php
declare(strict_types=1);
namespace DigiForge\Tests;
use PHPUnit\Framework\TestCase;
use DigiForge\POD\PrintifyAcceptanceOperationalPolicy as Policy;
if(is_file(__DIR__.'/../../includes/POD/PrintifyAcceptanceOperationalPolicy.php'))require_once __DIR__.'/../../includes/POD/PrintifyAcceptanceOperationalPolicy.php';
final class PrintifyAcceptanceOperationalPolicyTest extends TestCase {
 private function valid():array {self::assertTrue(class_exists(Policy::class));return ['capability'=>'printify.acceptance.read','method'=>'GET','policy_sha256'=>Policy::REVISION1_SHA256,'implementation_certified'=>true,'installation_authorized'=>true,'operational_authorized'=>true,'independent_review_valid'=>true,'owner_actor_id'=>1,'owner_verified'=>true,'session_bound'=>true,'binding_verified'=>true,'credential_association_verified'=>true,'internal_shop_id'=>2,'shop_key'=>'personalized_pod','integration_id'=>3,'provider_shop_id'=>'28930593','environment'=>'production','integration_enabled'=>false,'stop_all'=>true,'external_lock'=>true,'automation_armed'=>false,'activation_authorized'=>false,'release_hold'=>true,'generation_current'=>true,'audit_available'=>true,'issued_at'=>1000,'expires_at'=>1300];}
 public function testAllEvidenceRequiredAndDefaultDenies():void {self::assertTrue(class_exists(Policy::class));self::assertFalse(Policy::evaluate([],1100)['eligible']);$e=$this->valid();self::assertTrue(Policy::evaluate($e,1100)['eligible']);foreach(array_keys($e) as $k){$m=$e;unset($m[$k]);self::assertFalse(Policy::evaluate($m,1100)['eligible'],$k);}}
 public function testMutationsNeverAdmitted():void {$e=$this->valid();foreach(['POST','PUT','PATCH','DELETE','HEAD'] as $m){$e['method']=$m;self::assertFalse(Policy::evaluate($e,1100)['eligible']);}}
 public function testIdentityAndOrdinaryActivationCannotBorrowException():void {$e=$this->valid();foreach(['capability'=>'PROVIDER_ORDER_SUBMIT','owner_actor_id'=>2,'internal_shop_id'=>3,'shop_key'=>'standard_pod','integration_id'=>4,'provider_shop_id'=>'28925875','environment'=>'test','integration_enabled'=>true,'automation_armed'=>true,'activation_authorized'=>true,'release_hold'=>false,'generation_current'=>false,'audit_available'=>false,'policy_sha256'=>str_repeat('0',64)] as $k=>$v){$m=$e;$m[$k]=$v;self::assertFalse(Policy::evaluate($m,1100)['eligible'],$k);}}
 public function testExpiredFutureOverlongAndUnverifiedEvidenceDenied():void {$e=$this->valid();foreach([999,1300,1400] as $now)self::assertFalse(Policy::evaluate($e,$now)['eligible']);$e['expires_at']=1301;self::assertFalse(Policy::evaluate($e,1100)['eligible']);foreach(['implementation_certified','installation_authorized','operational_authorized','independent_review_valid','binding_verified','credential_association_verified'] as $k){$m=$this->valid();$m[$k]='true';self::assertFalse(Policy::evaluate($m,1100)['eligible']);}}
}
